+// Coerces any caught value to an Error, preserving the original as cause.
+function toError(error: unknown): Error {
+  if (error instanceof Error) return error;
+  const message =
+    typeof error === 'string'
+      ? error
+      : typeof error === 'object' && error !== null
+        ? tryStringify(error)
+        : String(error);
+  return new Error(message, {cause: error});
+}
+
+// A failed serialization falls back to String() rather than throwing in error handling.
+function tryStringify(value: object): string {
+  try {
+    return JSON.stringify(value);
+  } catch {
+    return String(value);
+  }
+}

